 79	const parseForwarded = (value) => {
 80	  if (typeof value !== 'string' || value.length === 0 || value.length > 512) throw new TypeError('invalid forwarding chain');
 81	  const elements = value.split(',');
 82	  if (elements.length > 16) throw new TypeError('invalid forwarding chain');
 83	  return elements.map((element) => {
 84	    const fields = Object.create(null);
 85	    for (const parameter of element.split(';')) {
 86	      const match = /^([a-z]+)=("[^"]+"|[^\s;,]+)$/i.exec(parameter.trim());
 87	      if (!match || Object.hasOwn(fields, match[1].toLowerCase())) throw new TypeError('invalid forwarding chain');
 88	      let decoded = match[2];
 89	      if (decoded.startsWith('"')) decoded = decoded.slice(1, -1);
 90	      if (!/^[A-Za-z0-9.:[\]_%+-]+$/.test(decoded)) throw new TypeError('invalid forwarding chain');
 91	      fields[match[1].toLowerCase()] = decoded;
 92	    }
 93	    if (!fields.for || !fields.proto || Object.keys(fields).some((key) => !['for', 'proto'].includes(key))) throw new TypeError('invalid forwarding chain');
 94	    fields.proto = fields.proto.toLowerCase();
 95	    if (!['http', 'https'].includes(fields.proto)) throw new TypeError('invalid forwarding chain');
 96	    let client = fields.for;
 97	    if (client.startsWith('[') && client.endsWith(']')) client = client.slice(1, -1);
 98	    if (client.includes(']') || client.includes('[') || client.includes('%')) throw new TypeError('invalid forwarding chain');
